    seconds = ledger.get('command_total_wall_seconds', ledger.get('wall_seconds', ledger.get('wall_seconds_so_far')))
    mismatches = sum((r.get('mismatch_count') or 0 for r in runs.values()))
    resource_failures = [r for r in runs.values() if r.get('failure_kind') == 'RESOURCE_LIMIT']
